CREATE OR REPLACE FUNCTION public.fn_get_event_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, title character varying, description text, event_type_id uuid, event_date date, start_time time without time zone, end_time time without time zone, location character varying, organizer_id uuid, status character varying, scope character varying, branch_id uuid, is_organization_wide boolean, photo_urls text[], created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT ev.id, ev.tenant_id, ev.title, ev.description, ev.event_type_id,            ev.event_date, ev.start_time, ev.end_time, ev.location, ev.organizer_id,            ev.status, ev.scope, ev.branch_id, ev.is_organization_wide,            ev.photo_urls, ev.created_at, ev.updated_at     FROM events ev     WHERE ev.id = p_id AND ev.tenant_id = p_tenant_id; END; $function$ ;
